 56→export class PlayerView implements OnInit, OnDestroy {
 57→  protected readonly store = inject(ExerciseStore);
 58→  protected readonly domain = inject(DomainService);
 59→  private readonly api = inject(EngineApiService);
 60→  private readonly decisionApi = inject(DecisionApiService);
 61→  protected readonly logsOpen = signal(false);
 62→  private readonly ws = inject(ExerciseWsService);
 63→  private readonly router = inject(Router);
 64→  private readonly route = inject(ActivatedRoute);
 65→  protected readonly roleLabel = signal("Advisor");
 66→  protected readonly beginningExercise = signal(false);
 67→  private readonly exerciseId = signal(1);
 68→  private readonly participantId = signal("");
 69→  private readonly tick = inject(TickService);
 70→  private snapshotLoaded = false;
 71→  private sub: Subscription | null = null;
 72→  private connSub: Subscription | null = null;
 73→
 74→  protected readonly activeDecisions = computed(() => {
 75→    const role = this.store.playerRole();
 76→    return this.store.openDecisions().filter((d) => {
 77→      if (!d.target_roles || d.target_roles.length === 0) return true;
 78→      if (role === "all_roles" || role === "all_advisors" || role === "solo_player") return true;
 79→      return d.target_roles.includes(role);
 80→    });
 81→  });
 82→
 83→  protected readonly isMultiRole = computed(() => {
 84→    const role = this.store.playerRole();
 85→    return role === "all_advisors" || role === "solo_player" || role === "all_roles";
 86→  });
 87→
 88→  protected readonly submittedRoles = signal<Set<string>>(new Set());
 89→
 90→  protected readonly currentTurnEvent = computed(() => {
 91→    const decisions = this.activeDecisions();
 92→    if (decisions.length === 0) return null;
 93→    const decision = decisions[0];
 94→    if (!decision.event_id) return null;
 95→    return this.store.events().find((e) => e.id === decision.event_id) ?? null;
 96→  });
 97→
 98→  protected readonly roleCards = computed(() => {
 99→    const allRoles = this.store.context()?.roles ?? [];
100→    const event = this.currentTurnEvent();
101→    const decision = this.activeDecisions()[0] ?? null;
102→    const role = this.store.playerRole();
103→    const multiRole = this.isMultiRole();
104→    const playerRoleDef = allRoles.find((r) => r.id === role);
105→    const showDecisionMaker =
106→      role === "all_roles" || role === "solo_player" || this.store.isPracticeMode()
107→      || playerRoleDef?.player_type === "decision_maker";
108→    // Single-role players see only their own role card
109→    const roles = multiRole ? allRoles : allRoles.filter((r) => r.id === role);
110→    return buildRoleCards(roles, event, decision, this.submittedRoles(), showDecisionMaker, allRoles);
111→  });
112→
113→  private _lastDecisionId: string | null = null;
114→  private readonly resetSubmittedRolesEffect = effect(() => {
115→    const id = this.activeDecisions()[0]?.id ?? null;
116→    // Only reset when the decision ID actually changes (not on every WS push)
117→    if (id && id !== this._lastDecisionId) {
118→      this._lastDecisionId = id;
119→      this.submittedRoles.set(new Set());
120→    }
121→  });
122→
123→  // Turn advancement is backend-driven: closing a decision triggers the
124→  // next event in sequence automatically via engine.force_trigger_next_decision.
125→
126→  ngOnInit(): void {
127→    const params = this.route.snapshot.queryParams;
128→    const id = Number(params["exerciseId"] ?? 1);
129→    const pId = String(params["participantId"] ?? "");
130→    const role = String(params["role"] ?? "player");
131→    const gameMode = String(params["gameMode"] ?? "");
132→    this.exerciseId.set(id);
133→    this.participantId.set(pId);
134→    this.store.setParticipantId(pId);
135→    this.store.setPlayerRole(role);
136→    if (gameMode) {
137→      this.store.setGameMode(gameMode);
138→    }
139→    const practiceMode = params["practiceMode"] === "true";
140→    this.store.setPracticeMode(practiceMode);
141→    this.ws.connect(id, "player", pId || undefined);
142→    this.sub = this.ws.messages$.subscribe((msg) =>
143→      handlePlayerWsMessage(msg, this.store, () => this.onExerciseStopped(), this.ws),
144→    );
145→    this.loadSnapshot(id);
146→    this.decisionApi.getContext(id).subscribe({
147→      next: (ctx) =>
148→        resolvePlayerRole(ctx, role, gameMode, this.store, this.roleLabel),
149→      error: () => {},
150→    });
151→    this.decisionApi.getEngineDecisions(id).subscribe({
152→      next: (decisions) => this.store.applyDecisions(decisions),
153→      error: () => {},
154→    });
155→    this.connSub = this.ws.connected$.subscribe((connected) => {
156→      if (connected && this.snapshotLoaded) this.loadSnapshot(id);
157→    });
158→    this.tick.start(this.store);
159→  }
160→
161→  private loadSnapshot(exerciseId: number): void {
162→    this.api.snapshot(exerciseId).subscribe({
163→      next: (snap) => {
164→        this.snapshotLoaded = true;
165→        this.store.applySnapshot(snap);
166→      },
167→      error: () => this.store.setError("Failed to load snapshot"),
168→    });
169→  }
170→
171→  protected onBeginExercise(): void {
172→    this.beginningExercise.set(true);
173→    this.api.begin(this.exerciseId()).subscribe({
174→      next: (change) => {
175→        this.store.applyPhaseChange(change.phase);
176→        this.store.applyTimeUpdate(change.time);
177→        this.beginningExercise.set(false);
178→      },
179→      error: () => {
180→        this.store.setError("Failed to begin exercise");
181→        this.beginningExercise.set(false);
182→      },
183→    });
184→  }
185→
186→  protected onStop(): void {
187→    this.api.stop(this.exerciseId()).subscribe({
188→      next: () => this.onExerciseStopped(),
189→    });
190→  }
191→
192→  protected onExerciseStopped(): void {
193→    this.ws.disconnect();
194→    this.router.navigate(["/"]);
195→  }
196→
197→  ngOnDestroy(): void {
198→    this.tick.stop();
199→    this.ws.disconnect();
200→    this.sub?.unsubscribe();
201→    this.connSub?.unsubscribe();
202→  }
203→  protected onRoleCardSubmitted(submission: RoleCardSubmission): void {
204→    const decision = this.activeDecisions()[0];
205→    if (!decision) return;
206→    const role = this.store.context()?.roles?.find(
207→      (r) => r.id === submission.roleId,
208→    );
209→    if (role?.player_type === "decision_maker") {
210→      submitDecision(
211→        this.decisionApi,
212→        this.store,
213→        this.exerciseId(),
214→        decision,
215→        submission,
216→      );
217→    } else {
218→      submitRoleRecommendation(
219→        this.decisionApi,
220→        this.exerciseId(),
221→        decision,
222→        this.participantId(),
223→        { roleId: submission.roleId, selectedOptions: submission.selectedOptions, freeText: submission.freeText },
224→      );
225→    }
226→    const updated = new Set(this.submittedRoles());
227→    updated.add(submission.roleId);
228→    this.submittedRoles.set(updated);
229→  }
230→}
