17→      [class.playing-card--recommended]="recommended()"
18→      [class.playing-card--disabled]="disabled()"
19→      [disabled]="disabled()"
20→      (click)="clicked.emit()"
21→    >
22→      @if (option().role) {
23→        <span
24→          class="playing-card__role-badge"
25→          [attr.data-role]="option().role"
26→          >{{ roleAbbrev() }}</span
27→        >
28→      }
29→      <span class="playing-card__code">{{ option().id }}</span>
30→      <span class="playing-card__label">{{ option().label }}</span>
31→      <span
32→        class="playing-card__score"
33→        [attr.data-sign]="scoreSign()"
34→        >{{ scoreDisplay() }}</span
35→      >
36→      @if (recommended()) {
37→        <span class="playing-card__rec-badge">REC</span>
38→      }
39→    </button>
40→  `,
41→})
42→export class PlayingCardComponent {
43→  readonly option = input.required<DecisionOption>();
44→  readonly selected = input(false);
45→  readonly recommended = input(false);
46→  readonly disabled = input(false);
47→  readonly clicked = output();
48→
49→  protected readonly roleAbbrev = computed(() => {
50→    const role = this.option().role;
51→    return role ? role.toUpperCase() : "";
52→  });
53→
54→  protected readonly scoreSign = computed(() => {
55→    const score = this.option().score ?? 0;
56→    if (score > 0) return "positive";
57→    if (score < 0) return "negative";
58→    return "zero";
59→  });
60→
61→  protected readonly scoreDisplay = computed(() => {
62→    const score = this.option().score ?? 0;
