 41→  title: string;
 42→  phase: string;
 43→  gameMode: string;
 44→  practiceMode: boolean;
 45→  playTimeMs: number;
 46→  realTimeMs: number;
 47→  speedFactor: number;
 48→  paused: boolean;
 49→  events: EventSnapshot[]; // domain: "injects"
 50→  issues: IssueSnapshot[]; // domain: "defects"
 51→  decisions: ActiveDecision[];
