 62→}
 63→
 64→const initialState: ExerciseState = {
 65→  exerciseId: null,
 66→  title: "",
 67→  phase: "setup",
 68→  gameMode: "classic",
 69→  practiceMode: false,
 70→  playTimeMs: 0,
 71→  realTimeMs: 0,
 72→  speedFactor: 1,
 73→  paused: true,
 74→  events: [],
 75→  issues: [],
 76→  decisions: [],
 77→  systems: [],
 78→  warfareDomains: [],
 79→  participants: [],
 80→  context: null,
