235→export class GameMasterView implements OnInit, OnDestroy {
236→  protected readonly store = inject(ExerciseStore);
237→  protected readonly domain = inject(DomainService);
238→  private readonly api = inject(EngineApiService);
239→  private readonly exerciseApi = inject(ExerciseApiService);
240→  private readonly decisionApi = inject(DecisionApiService);
241→  private readonly ws = inject(ExerciseWsService);
242→  private readonly router = inject(Router);
243→  private readonly route = inject(ActivatedRoute);
244→  protected readonly selectedDecision = signal<DecisionDetail | null>(null);
245→  protected readonly exerciseId = signal<number | null>(null);
246→  protected readonly logsOpen = signal(false);
247→  private sub: Subscription | null = null;
248→  private connSub: Subscription | null = null;
249→  private readonly tick = inject(TickService);
250→
251→  ngOnInit(): void {
252→    const params = this.route.snapshot.queryParams;
253→    const eId = Number(params["exerciseId"] ?? 0);
254→    if (eId) {
255→      this.exerciseId.set(eId);
256→      this.connectExercise(eId);
257→    }
258→  }
259→
260→  protected onExerciseSelected(exercise: ExerciseResponse): void {
261→    if (exercise.domain_id != null) {
262→      const domainMap: Record<number, string> = {
263→        1: "cybersecurity",
264→        2: "healthcare",
265→        3: "military",
266→      };
267→      this.domain.setDomain(domainMap[exercise.domain_id] ?? "default");
268→    }
269→    this.exerciseId.set(exercise.id);
270→    this.connectExercise(exercise.id);
271→  }
272→
273→  protected onScenarioSelected({
274→    scenario,
275→    gameMode,
276→  }: ScenarioSelection): void {
277→    if (scenario.domain_id != null) {
278→      const domainMap: Record<number, string> = {
279→        1: "cybersecurity",
280→        2: "healthcare",
281→        3: "military",
282→      };
283→      this.domain.setDomain(domainMap[scenario.domain_id] ?? "default");
284→    }
285→    this.exerciseApi
286→      .create({
287→        title: scenario.title,
288→        scenario_id: scenario.id,
289→        time_factor: scenario.content?.default_time_factor ?? 1.0,
290→        game_mode: gameMode,
291→      })
292→      .subscribe({
293→        next: (ex) => {
294→          this.router.navigate(["/waiting-room"], {
295→            queryParams: { exerciseId: ex.id },
296→          });
297→        },
298→        error: () => this.store.setError("Failed to create exercise"),
299→      });
300→  }
301→
302→  private connectExercise(id: number): void {
303→    this.ws.connect(id, "gm");
304→    this.sub = this.ws.messages$.subscribe((msg) =>
305→      handleGmWsMessage(msg, this.store, () => this.onExerciseStopped()),
306→    );
307→    this.loadSnapshot(id);
308→    this.decisionApi
309→      .getContext(id)
310→      .subscribe({ next: (ctx) => this.store.setContext(ctx) });
311→    this.connSub = this.ws.connected$.subscribe((c) => {
312→      if (c) this.loadSnapshot(id);
313→    });
314→    this.tick.start(this.store);
315→  }
316→
317→  ngOnDestroy(): void {
318→    this.tick.stop();
319→    this.ws.disconnect();
320→    this.sub?.unsubscribe();
321→    this.connSub?.unsubscribe();
322→  }
323→
324→  private loadSnapshot(id: number): void {
325→    this.api.snapshot(id).subscribe({
326→      next: (snap) => this.store.applySnapshot(snap),
327→      error: () => this.store.setError("Failed to load snapshot"),
328→    });
329→  }
330→
331→  protected viewDecision(id: string): void {
332→    this.decisionApi.getDecisionDetail(Number(id)).subscribe({
333→      next: (detail) => this.selectedDecision.set(detail),
334→    });
335→  }
336→
337→  protected closeDecision(id: string): void {
338→    this.decisionApi.closeEngineDecision(this.exerciseId()!, id).subscribe({
339→      next: () => this.store.closeDecision(id),
340→    });
341→  }
342→
343→  protected onStart(): void {
344→    startExercise(this.api, this.store, this.exerciseId()!);
345→  }
346→  protected onPause(): void {
347→    pauseExercise(this.api, this.store, this.exerciseId()!);
348→  }
349→  protected onReset(): void {
350→    resetExercise(this.api, this.store, this.exerciseId()!);
351→  }
352→  protected onComplete(): void {
353→    completeExercise(this.api, this.store, this.exerciseId()!);
354→  }
355→  protected onStop(): void {
356→    stopExercise(this.api, this.exerciseId()!, () => this.onExerciseStopped());
357→  }
358→  private onExerciseStopped(): void {
359→    this.ws.disconnect();
360→    this.router.navigate(["/"]);
361→  }
362→  protected onSpeedChange(e: Event): void {
363→    const target = e.target;
364→    if (!(target instanceof HTMLInputElement)) return;
365→    this.api.setSpeed(this.exerciseId()!, parseFloat(target.value)).subscribe();
366→  }
367→
368→  private eid(): number {
369→    return this.exerciseId()!;
370→  }
371→  protected triggerEvent(id: string): void {
372→    this.api.triggerEvent(this.eid(), id).subscribe();
373→  }
374→  protected cancelEvent(id: string): void {
375→    this.api.cancelEvent(this.eid(), id).subscribe();
376→  }
377→  protected completeEvent(id: string): void {
378→    this.api.completeEvent(this.eid(), id).subscribe();
379→  }
380→  protected activateIssue(id: string): void {
381→    this.api.activateIssue(this.eid(), id).subscribe();
382→  }
383→  protected mitigateIssue(id: string): void {
384→    this.api.mitigateIssue(this.eid(), id).subscribe();
385→  }
386→  protected resolveIssue(id: string): void {
387→    this.api.resolveIssue(this.eid(), id).subscribe();
388→  }
389→}
