 39→@Component({
 40→  selector: "tfc-player-view",
 41→  changeDetection: ChangeDetectionStrategy.OnPush,
 42→  providers: [ExerciseStore, TickService],
 43→  imports: [
 44→    ClockDisplayComponent,
 45→    PhaseBadgeComponent,
 46→    AmbientBackgroundComponent,
 47→    BriefingOverlayComponent,
 48→    CompletionOverlayComponent,
 49→    LogsDrawerComponent,
 50→    StressBarComponent,
 51→    ButtonDirective,
 52→    RoleCardComponent,
 53→    SystemStatusBoardComponent,
 54→    WarfareDomainBoardComponent,
 55→  ],
 56→  templateUrl: "./player-view.html",
 57→})
 58→export class PlayerView implements OnInit, OnDestroy {
 59→  protected readonly store = inject(ExerciseStore);
 60→  protected readonly domain = inject(DomainService);
 61→  private readonly api = inject(EngineApiService);
 62→  private readonly decisionApi = inject(DecisionApiService);
 63→  protected readonly logsOpen = signal(false);
 64→  private readonly ws = inject(ExerciseWsService);
 65→  private readonly router = inject(Router);
 66→  private readonly route = inject(ActivatedRoute);
 67→  protected readonly roleLabel = signal("Advisor");
 68→  protected readonly beginningExercise = signal(false);
 69→  private readonly exerciseId = signal(1);
 70→  private readonly participantId = signal("");
 71→  private readonly tick = inject(TickService);
 72→  private snapshotLoaded = false;
 73→  private sub: Subscription | null = null;
 74→  private connSub: Subscription | null = null;
 75→
 76→  protected readonly activeDecisions = computed(() => {
 77→    const role = this.store.playerRole();
 78→    return this.store.openDecisions().filter((d) => {
 79→      if (!d.target_roles || d.target_roles.length === 0) return true;
 80→      if (
 81→        role === "all_roles" ||
 82→        role === "all_advisors" ||
 83→        role === "solo_player"
 84→      )
 85→        return true;
 86→      return d.target_roles.includes(role);
 87→    });
 88→  });
 89→
 90→  protected readonly isMultiRole = computed(() => {
 91→    const role = this.store.playerRole();
 92→    return (
 93→      role === "all_advisors" || role === "solo_player" || role === "all_roles"
 94→    );
 95→  });
 96→
 97→  protected readonly submittedRoles = signal<Set<string>>(new Set());
 98→
 99→  protected readonly currentTurnEvent = computed(() => {
100→    const decisions = this.activeDecisions();
101→    if (decisions.length === 0) return null;
102→    const decision = decisions[0];
103→    if (!decision.event_id) return null;
104→    return this.store.events().find((e) => e.id === decision.event_id) ?? null;
105→  });
106→
107→  protected readonly roleCards = computed(() => {
108→    const allRoles = this.store.context()?.roles ?? [];
109→    const event = this.currentTurnEvent();
110→    const decision = this.activeDecisions()[0] ?? null;
111→    const role = this.store.playerRole();
112→    const multiRole = this.isMultiRole();
113→    const playerRoleDef = allRoles.find((r) => r.id === role);
114→    const showDecisionMaker =
115→      role === "all_roles" ||
116→      role === "solo_player" ||
117→      this.store.isPracticeMode() ||
118→      playerRoleDef?.player_type === "decision_maker";
119→    // Single-role players see only their own role card
120→    const roles = multiRole ? allRoles : allRoles.filter((r) => r.id === role);
121→    return buildRoleCards(
122→      roles,
123→      event,
124→      decision,
125→      this.submittedRoles(),
126→      showDecisionMaker,
127→      allRoles,
128→    );
129→  });
130→
131→  private _lastDecisionId: string | null = null;
132→  private readonly resetSubmittedRolesEffect = effect(() => {
133→    const id = this.activeDecisions()[0]?.id ?? null;
134→    // Only reset when the decision ID actually changes (not on every WS push)
135→    if (id && id !== this._lastDecisionId) {
136→      this._lastDecisionId = id;
137→      this.submittedRoles.set(new Set());
138→    }
139→  });
140→
141→  // Turn advancement is backend-driven: closing a decision triggers the
142→  // next event in sequence automatically via engine.force_trigger_next_decision.
143→
144→  ngOnInit(): void {
145→    const params = this.route.snapshot.queryParams;
146→    const id = Number(params["exerciseId"] ?? 1);
147→    const pId = String(params["participantId"] ?? "");
148→    const role = String(params["role"] ?? "player");
149→    const gameMode = String(params["gameMode"] ?? "");
150→    this.exerciseId.set(id);
151→    this.participantId.set(pId);
152→    this.store.setParticipantId(pId);
153→    this.store.setPlayerRole(role);
154→    if (gameMode) {
155→      this.store.setGameMode(gameMode);
156→    }
157→    const practiceMode = params["practiceMode"] === "true";
158→    this.store.setPracticeMode(practiceMode);
159→    this.ws.connect(id, "player", pId || undefined);
160→    this.sub = this.ws.messages$.subscribe((msg) =>
161→      handlePlayerWsMessage(
162→        msg,
163→        this.store,
164→        () => this.onExerciseStopped(),
165→        this.ws,
166→      ),
167→    );
168→    this.loadSnapshot(id);
169→    this.decisionApi.getContext(id).subscribe({
170→      next: (ctx) =>
171→        resolvePlayerRole(ctx, role, gameMode, this.store, this.roleLabel),
172→      error: () => {},
173→    });
174→    this.decisionApi.getEngineDecisions(id).subscribe({
175→      next: (decisions) => this.store.applyDecisions(decisions),
176→      error: () => {},
177→    });
178→    this.connSub = this.ws.connected$.subscribe((connected) => {
179→      if (connected && this.snapshotLoaded) this.loadSnapshot(id);
180→    });
181→    this.tick.start(this.store);
182→  }
183→
184→  private loadSnapshot(exerciseId: number): void {
185→    this.api.snapshot(exerciseId).subscribe({
186→      next: (snap) => {
187→        this.snapshotLoaded = true;
188→        this.store.applySnapshot(snap);
189→      },
190→      error: () => this.store.setError("Failed to load snapshot"),
191→    });
192→  }
193→
194→  protected onBeginExercise(): void {
195→    this.beginningExercise.set(true);
196→    this.api.begin(this.exerciseId()).subscribe({
197→      next: (change) => {
198→        this.store.applyPhaseChange(change.phase);
199→        this.store.applyTimeUpdate(change.time);
200→        this.beginningExercise.set(false);
201→      },
202→      error: () => {
203→        this.store.setError("Failed to begin exercise");
204→        this.beginningExercise.set(false);
205→      },
206→    });
207→  }
208→
209→  protected onStop(): void {
210→    this.api.stop(this.exerciseId()).subscribe({
211→      next: () => this.onExerciseStopped(),
212→    });
213→  }
214→
215→  protected onExerciseStopped(): void {
216→    this.ws.disconnect();
217→    this.router.navigate(["/"]);
218→  }
219→
220→  ngOnDestroy(): void {
221→    this.tick.stop();
222→    this.ws.disconnect();
223→    this.sub?.unsubscribe();
224→    this.connSub?.unsubscribe();
225→  }
226→  protected onRoleCardSubmitted(submission: RoleCardSubmission): void {
227→    const decision = this.activeDecisions()[0];
228→    if (!decision) return;
229→    const role = this.store
230→      .context()
231→      ?.roles?.find((r) => r.id === submission.roleId);
232→    if (role?.player_type === "decision_maker") {
233→      submitDecision(
234→        this.decisionApi,
235→        this.store,
236→        this.exerciseId(),
237→        decision,
238→        submission,
239→      );
240→    } else {
241→      submitRoleRecommendation(
242→        this.decisionApi,
243→        this.exerciseId(),
244→        decision,
245→        this.participantId(),
246→        {
247→          roleId: submission.roleId,
248→          selectedOptions: submission.selectedOptions,
249→          freeText: submission.freeText,
250→        },
251→      );
252→    }
253→    const updated = new Set(this.submittedRoles());
254→    updated.add(submission.roleId);
255→    this.submittedRoles.set(updated);
256→  }
257→}
