+      completion_mode: "any",
+      target_roles: ["co"],
+      timeout_ms: 30_000,
+      max_selections: null,
+      status: "open",
+      opened_at_pt_ms: 0,
+      closed_at_pt_ms: null,
+      recommendations: {},
+      selected_option_ids: [],
+    },
+    status: "active",
+    advisorRecs: [],
+    ...overrides,
+  };
+}
+
+function makeSystems(): SystemSnapshot[] {
+  return [
+    {
+      system_id: "radar",
+      label: "RADAR",
+      category: "sensor",
+      power: true,
+      operational: "operational",
+    },
+    {
+      system_id: "sonar",
+      label: "SONAR",
+      category: "sensor",
+      power: true,
+      operational: "operational",
+    },
+  ];
+}
+
+@Component({
+  imports: [RoleCardComponent],
+  template: `
+    <tfc-role-card
+      [card]="card()"
+      [systems]="systems()"
